create table s_assignment (id bigint generated by default as identity, assoc_form_name varchar(100), assoc_name varchar(150) not null, assoc_spec_id bigint not null, assoc_wo_name varchar(100), dependent_flag boolean, form_name varchar(100), spec_id bigint not null, wo_name varchar(100), primary key (id));
create table s_state (id bigint generated by default as identity, wo_name varchar(100) not null, wo_state varchar(100) not null, primary key (id));
create table s_state_transit (id_state_transit bigint generated by default as identity, action_label varchar(100) not null, action_name varchar(100) not null, class_name varchar(1000), close_window boolean, current_state varchar(100) not null, custom_url varchar(500), default_display boolean, method_name varchar(150), next_state varchar(100) not null, read_only boolean, secondary_action boolean, wo_name varchar(100) not null, primary key (id_state_transit));
create table s_statetransit_subact_attribute (id bigint generated by default as identity, const_value varchar(100) not null, field_name varchar(100) not null, id_state_transit bigint not null, id_statetransit_subact bigint not null, primary key (id));
create table s_statetransit_subact_inclusion (id bigint generated by default as identity, exclusion boolean, id_state_transit bigint not null, id_statetransit_subact bigint not null, inclusion boolean, primary key (id));
create table s_statetransit_subaction (id_statetransit_subact bigint generated by default as identity, action_name varchar(100) not null, id_state_transit bigint not null, process_name varchar(150), primary key (id_statetransit_subact));
